const $=s=>document.querySelector(s);
let costingRecipeId='',pricingId='';
const content=$('#content');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const currency=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((n||0)/100);
const today=()=>new Date().toLocaleDateString('en-CA');
const sourceName=s=>({main:'Brew main app',vendor:'Vendor Ordering',manual:'Business accounting',provider:'Gusto Payroll'}[s]||s);
const badge=s=>`<span class="badge ${esc(s)}">${esc(sourceName(s))}</span>`;
let state,view='overview',rows=[],pendingImport=null,start='',end='',source='',search='';
let refreshTimer;
const labels={overview:'Overview',transactions:'Company ledger',invoices:'Invoices & payments',bills:'Bills & expenses',reconcile:'Bank reconciliation',costing:'Production costs',pricing:'Retail & wholesale pricing',inventory:'Inventory planning',assets:'Equipment & depreciation',payroll:'Payroll & employees',taxes:'Tax updates & liabilities',printing:'Print Center',reports:'Financial reports',accounts:'Chart of accounts',imports:'App connections',settings:'Settings & audit'};
async function api(path,value){const res=await fetch(path,value===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Accounting-Request':'1'},body:JSON.stringify(value)});const data=await res.json();if(!res.ok)throw Error(data.error||'Request failed');return data;}
function notice(message,error=false){const n=$('#notice');n.hidden=false;n.textContent=message;n.className=error?'error':'';if($('#detail').open){let local=$('#dialog-notice');if(!local){local=document.createElement('p');local.id='dialog-notice';local.setAttribute('role','alert');$('#detail-content').prepend(local);}local.textContent=message;local.className=error?'amount-negative':'';local.scrollIntoView({block:'nearest'});}else n.scrollIntoView({block:'nearest'});}
function formValue(form){return Object.fromEntries(new FormData(form));}
const empty=(title,body)=>`<div class="empty"><span class="card-icon">◇</span><strong>${esc(title)}</strong>${esc(body)}</div>`;
const title=(name,desc,actions='')=>`<div class="page-title"><div><div class="eyebrow">YOUR COMPANY, CONNECTED</div><h1>${name}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;
const table=(heads,body)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th${['Debit','Credit','Amount','Balance','Net debit','Subtotal','Total'].includes(h)?' class="amount"':''}>${esc(h)}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`;
const options=(type=null,selected='')=>state.accounts.filter(a=>!type||a.type===type).map(a=>`<option value="${a.code}" ${a.code===selected?'selected':''}>${a.code} · ${esc(a.name)}</option>`).join('');
function filters(includeSource=false){return `<form id="filters" class="filters"><label>From<input name="start" type="date" value="${esc(start)}"></label><label>Through<input name="end" type="date" value="${esc(end)}"></label>${includeSource?`<label>Trace source<select name="source"><option value="">All apps · combined books</option>${['main','vendor','manual'].map(s=>`<option value="${s}" ${source===s?'selected':''}>${sourceName(s)}</option>`).join('')}</select></label>`:''}<button>Apply</button><button type="button" data-action="reset-filters">All dates</button></form>`;}
function documentButton(d,label='View'){return `<button data-action="document" data-source="${esc(d.source)}" data-id="${esc(d.source_id)}">${label}</button>`;}
function documentTable(docs){return docs.length?table(['Date','Reference','Customer / supplier','Source','Amount','Balance',''],docs.map(d=>`<tr><td>${esc(d.date)}</td><td>${esc(d.reference)}<small class="muted"> · ${esc(d.kind)}</small></td><td>${esc(d.party||'—')}</td><td>${badge(d.source)}</td><td class="amount">${currency(d.amount)}</td><td class="amount">${currency(d.balance)}</td><td>${documentButton(d)} ${(d.source==='manual'||d.source==='vendor'&&d.kind==='purchase-receipt')&&d.balance>0?`<button data-action="pay" data-source="${esc(d.source)}" data-id="${esc(d.source_id)}">Payment</button>`:''}</td></tr>`).join('')):empty('No records yet','Connect your apps or add a transaction to get started.');}
function reviewCount(){return state.documents.filter(d=>d.kind==='needs-cost').length;}
function overview(){const r=state.report;const hasData=state.documents.length>0;return title('Your business, all together.','One set of books for Backwoods Brew and Vendor Ordering.',`<button data-view="imports">⇣ Connect your apps</button><button class="primary" data-action="new-document">+ New transaction</button>`)+filters()+
`${reviewCount()?`<div class="banner warning"><span>!</span><div><strong>${reviewCount()} inventory costs need review</strong><p>Profit and inventory are incomplete until historical costs are supplied. <button class="link" data-view="imports">Review records</button></p></div></div>`:''}`+
`<div class="cards"><div class="card"><div class="card-label">Sales revenue, net <span class="card-icon">↗</span></div><strong>${currency(r.income)}</strong><small>${start||end?'Selected period':'All imported dates'}</small></div><div class="card"><div class="card-label">Expenses & cost of sales <span class="card-icon">↙</span></div><strong>${currency(r.expense)}</strong><small>All connected business activity</small></div><div class="card featured"><div class="card-label">Net profit <span>◈</span></div><strong>${currency(r.profit)}</strong><small>${reviewCount()?'Historical costs pending review':'Income less expenses · accrual basis'}</small></div><div class="card"><div class="card-label">Accounts receivable <span class="card-icon">◷</span></div><strong>${currency(r.trial.find(a=>a.code==='1100')?.balance||0)}</strong><small>Company total as of ${esc(end||'latest import')}</small></div></div>`+
`<div class="two-col"><section class="panel"><div class="panel-head"><h2>Business performance</h2><span class="pill">COMBINED COMPANY</span></div>${hasData?`<div class="bar-chart">${[['Revenue',r.income,''],['Expenses',r.expense,'gold']].map(([name,val,cls])=>`<div class="bar-row"><span class="muted">${name}</span><div class="bar-track"><div class="bar-fill ${cls}" data-width="${Math.max(0,val)/Math.max(1,Math.abs(r.income),Math.abs(r.expense))*100}"></div></div><strong>${currency(val)}</strong></div>`).join('')}</div><div class="report-total"><span>Net profit</span><span>${currency(r.profit)}</span></div>`:empty('Your company picture starts here','Import current backups or enable the app connectors. No sample transactions are included.')}<p class="small muted">Both apps feed the same accounts. Source labels are for tracing individual records.</p></section><section class="panel"><div class="panel-head"><h2>Books at a glance</h2><span class="badge">${r.debits===r.credits?'Balanced':'Review needed'}</span></div><div class="health-row"><span>Bank & cash</span><strong>${currency(r.trial.filter(a=>['1010','1020'].includes(a.code)).reduce((s,a)=>s+a.balance,0))}</strong></div><div class="health-row"><span>Undeposited collections</span><strong>${currency(r.trial.find(a=>a.code==='1030')?.balance||0)}</strong></div><div class="health-row"><span>Bills payable</span><strong>${currency(-(r.trial.find(a=>a.code==='2000')?.balance||0))}</strong></div><div class="health-row"><span>Sales tax payable</span><strong>${currency(-(r.trial.find(a=>a.code==='2100')?.balance||0))}</strong></div><div class="health-row"><span>Last import</span><strong>${esc(state.batches[0]?.created_at.slice(0,16).replace('T',' ')||'Not connected')}</strong></div></section></div>`+
`<section class="panel"><div class="panel-head"><h2>Recent company records</h2><button class="link" data-view="transactions">View company ledger →</button></div>${documentTable(state.documents.filter(d=>!d.kind.startsWith('support-')).slice(0,7))}</section><div class="banner"><span>↳</span><div><strong>Your main app keeps its accounting.</strong><p>This app receives records in one direction and merges them into your company books. It never writes changes back to the source apps.</p></div></div>`;}
function transactions(){const q=search.toLowerCase();const filtered=rows.filter(r=>(!source||r.source===source)&&(!q||`${r.account} ${r.name} ${r.source_id} ${r.memo}`.toLowerCase().includes(q)));return title('One company ledger.','Every posted debit and credit, including source revisions and reversals.',`<a href="/api/export.csv?${new URLSearchParams({start,end})}">Export CSV</a><button class="primary" data-action="journal">+ Journal entry</button>`)+filters(true)+`<label>Find a transaction<input id="ledger-search" type="search" value="${esc(search)}" placeholder="Search account, reference or memo"></label><section class="panel"><div class="panel-head"><h2>${filtered.length} journal lines</h2><span class="pill">Combined company books</span></div>${filtered.length?table(['Date','Account','Reference / memo','Source','Debit','Credit',''],filtered.map(r=>`<tr><td>${esc(r.date)}</td><td><strong>${esc(r.account)}</strong> ${esc(r.name)}</td><td>${esc(r.source_id)}${r.reversal_of?` <span class="badge warn">Reversal</span>`:''}<div class="small muted">${esc(r.memo)}</div></td><td>${badge(r.source)}</td><td class="amount">${currency(r.debit)}</td><td class="amount">${currency(r.credit)}</td><td>${documentButton({source:r.source,source_id:r.source_id})}</td></tr>`).join('')):empty('No matching transactions','Try a different filter or import your app records.')}</section>`;}
function docsPage(kind){const invoice=kind==='invoices';const docs=state.documents.filter(d=>invoice?d.kind==='invoice'||d.kind==='support-invoices':['bill','expense','purchase-receipt','support-bills','support-expenses'].includes(d.kind));return title(invoice?'Invoices & payments':'Bills & expenses',invoice?'Customer invoices from both apps, with payments traced to their source.':'Supplier bills, received inventory and business expenses in one place.',`<button class="primary" data-action="new-document" data-kind="${invoice?'invoice':'bill'}">+ ${invoice?'New invoice':'New bill or expense'}</button>`)+`<div class="banner"><div><strong>Keep source records consistent.</strong><p>Record payments for imported invoices and bills in the original app. Add and pay business-accounting transactions here. Vendor inventory receipts accrue a payable. You can record their supplier payments here after confirming the supplier balance.</p></div></div><section class="panel">${documentTable(docs)}</section>${agingPanel(invoice)}`;}
function reports(){const r=state.report;return title('Financial reports','One company, one set of statements. Accrual basis · USD.',`<button data-action="print">Print reports</button><a href="/api/export.csv?${new URLSearchParams({start,end})}">Export ledger CSV</a>`)+filters()+`${reviewCount()?'<div class="banner warning"><div><strong>Historical inventory costs are missing.</strong><p>These reports exclude unresolved inventory cost postings. Resolve them in App connections.</p></div></div>':''}<div class="two-col equal"><section class="panel"><div class="panel-head"><h2>Profit & loss</h2><span class="pill">${esc(start||'Beginning')} — ${esc(end||'latest')}</span></div>${table(['Account','Amount'],r.profitLoss.map(a=>`<tr><td>${esc(a.code)} · ${esc(a.name)}</td><td class="amount">${currency(a.type==='income'?-a.balance:a.balance)}</td></tr>`).join(''))}<div class="health-row"><span>Net revenue</span><strong>${currency(r.income)}</strong></div><div class="health-row"><span>Expenses and cost of sales</span><strong>${currency(r.expense)}</strong></div><div class="report-total"><span>Net profit</span><span>${currency(r.profit)}</span></div><p class="small muted">Revenue is credited; discounts and sales returns reduce revenue.</p></section><section class="panel"><div class="panel-head"><h2>Balance sheet</h2><span class="pill">As of ${esc(end||'latest import')}</span></div>${table(['Account','Balance'],r.balanceSheet.map(a=>`<tr><td>${esc(a.code)} · ${esc(a.name)}</td><td class="amount">${currency(a.type==='asset'?a.balance:-a.balance)}</td></tr>`).join(''))}<div class="health-row"><span>Assets</span><strong>${currency(r.assets)}</strong></div><div class="health-row"><span>Liabilities</span><strong>${currency(r.liabilities)}</strong></div><div class="health-row"><span>Equity before earnings</span><strong>${currency(r.equity)}</strong></div><div class="health-row"><span>Cumulative earnings</span><strong>${currency(r.earnings)}</strong></div><div class="report-total"><span>Balance difference</span><span>${currency(r.balanceDifference)}</span></div></section></div><section class="panel"><h2>Trial balance · as of ${esc(end||'latest import')}</h2>${table(['Account','Debit','Credit','Net debit'],r.trial.map(a=>`<tr><td>${a.code} · ${esc(a.name)}</td><td class="amount">${currency(a.closingDebit)}</td><td class="amount">${currency(a.closingCredit)}</td><td class="amount">${currency(a.balance)}</td></tr>`).join(''))}<div class="report-total"><span>Total debits ${currency(r.trialDebits)}</span><span>Total credits ${currency(r.trialCredits)}</span></div></section>`;}
function accounts(){return title('Your chart of accounts','Both apps post to these shared company accounts.',`<button class="primary" data-action="account">+ Add account</button>`)+`<section class="panel">${table(['Code','Account name','Type'],state.accounts.map(a=>`<tr><td><strong>${a.code}</strong></td><td>${esc(a.name)}</td><td><span class="badge">${esc(a.type)}</span></td></tr>`).join(''))}</section>`;}
function imports(){return title('Two apps. One set of books.','Connect automatic local feeds or import an accounting backup. Your originals stay intact.')+`<div class="two-col equal"><section class="panel"><h2>App connections</h2><p class="muted small">Automatic transfers work when the connector-enabled source apps run on this computer. Records are picked up every few seconds while Business Accounting is open.</p>${['main','vendor'].map(s=>{const f=state.feeds[s];return `<div class="connection"><div class="connection-title"><span class="app-icon">${s==='main'?'B':'V'}</span><div><strong>${sourceName(s)}</strong><small>${s==='main'?'Main app accounting stays separate':'Invoices, collections, returns and inventory'}</small></div><span class="badge ${f?.ok?'':'warn'}">${f?f.ok?'Received':'Needs attention':'Not connected'}</span></div><small>${f?esc(f.error||`Received ${f.at.slice(0,19).replace('T',' ')} · ${f.added} new, ${f.changed} changed`):'No feed received yet'}</small></div>`}).join('')}<details><summary>Set up the desktop connectors</summary><ul class="instructions"><li>Use the included connector builder to create separate connected copies of your uploaded apps. It preserves the supplied originals.</li><li>The connected apps write snapshots to the shared local feed folder shown below. No Firebase credentials are needed for this local route.</li><li>Run the source app, sign in as the owner, and enable “Send to Business Accounting”. Leave Business Accounting open to receive changes.</li><li>Different computers require a secure shared backend; this build does not send records over the public internet.</li></ul><p class="path">${esc(state.feedDirectory)}</p></details></section><section class="panel"><h2>Import a backup</h2><p class="muted small">Choose a JSON backup exported by the main app or Vendor Ordering. Preview validation and review messages before committing.</p><form id="import-form"><label>Source app<select name="source"><option value="main">Backwoods Brew main app</option><option value="vendor">Vendor Ordering</option></select></label><label>Accounting backup<input type="file" name="file" accept=".json,application/json" required></label><button class="primary">Preview import</button></form><div id="import-preview"></div></section></div><section class="panel"><h2>Records needing historical cost</h2><p class="small muted">Older vendor movements did not always record their cost. Enter the actual unit cost from your source documents. Do not use today's catalog price as a historical cost.</p>${state.documents.some(d=>d.kind==='needs-cost')?table(['Date','Movement','Source',''],state.documents.filter(d=>d.kind==='needs-cost').map(d=>`<tr><td>${esc(d.date)}</td><td>${esc(d.reference)}</td><td>${badge(d.source)}</td><td>${documentButton(d)} <button data-action="cost" data-id="${esc(d.source_id.slice('inventory:'.length))}">Enter historical cost</button></td></tr>`).join('')):empty('No unresolved cost records','Missing costs will appear here when records are imported.')}</section><section class="panel"><h2>Import history</h2>${state.batches.length?table(['Received','Source','File','New','Revised','Duplicates'],state.batches.map(b=>`<tr><td>${esc(b.created_at.slice(0,19).replace('T',' '))}</td><td>${badge(b.source)}</td><td>${esc(b.filename)}</td><td>${b.added}</td><td>${b.changed}</td><td>${b.duplicates}</td></tr>`).join('')):empty('No imports yet','The first successful import will be recorded here.')}</section>`;}
function reconcile(){const bankRows=rows.filter(r=>r.account==='1020'&&!r.reconciliation_id);return title('Reconcile your bank','Match company journal lines to your bank statement. Finish only when the difference is zero.')+`<div class="two-col"><section class="panel"><h2>Unreconciled bank transactions</h2><p class="small muted">Select lines cleared on your statement. Enter missing fees, deposits or opening balances with a journal entry first. The first reconciliation starts at zero and includes your opening-balance entry.</p><form id="reconcile-form"><div class="form-grid"><label>Statement ending date<input type="date" name="date" value="${today()}" required></label><label>Account<select name="account"><option value="1020">1020 · Bank Account</option></select></label><label>Starting balance<input name="starting" type="number" step="0.01" value="${((state.reconciliations.find(r=>r.account==='1020')?.ending||0)/100).toFixed(2)}" required></label><label>Ending balance<input name="ending" type="number" step="0.01" required></label></div>${bankRows.length?table(['Cleared','Date','Reference','Amount'],bankRows.map(r=>`<tr><td><input type="checkbox" name="line" value="${r.id}" data-amount="${r.debit-r.credit}" aria-label="Clear ${esc(r.source_id)}"></td><td>${esc(r.date)}</td><td>${esc(r.source_id)}</td><td class="amount">${currency(r.debit-r.credit)}</td></tr>`).join('')):empty('No unreconciled bank lines','Import transactions or record an opening balance.')}<div class="report-total"><span>Statement difference</span><span id="reconcile-difference">Enter balances</span></div><button class="primary">Finish reconciliation</button></form></section><section class="panel"><h2>Statement matching</h2><p class="small muted">Optional CSV columns: date, description, amount. Deposits are positive and withdrawals negative. Suggestions select only unique amount matches; verify dates and descriptions yourself.</p><label>Bank statement CSV<input type="file" id="statement-file" accept=".csv,text/csv"></label><div id="statement-result"></div><h2>Completed statements</h2>${state.reconciliations.length?state.reconciliations.map(r=>`<div class="health-row"><span>${esc(r.date)}</span><strong>${currency(r.ending)}</strong></div>`).join(''):empty('No completed statements','Reconciliations are retained in the audit trail.')}</section></div>`;}
function baseSettings(){return title('Company settings & history','Back up your books, protect closed periods and review every import.')+`<div class="two-col equal"><section class="panel"><h2>Company</h2><form id="company-form"><label>Company name<input name="company" value="${esc(state.settings.company)}" required maxlength="200"></label><label>Business address for printed records<input name="company_address" value="${esc(state.settings.company_address||'')}" maxlength="200"></label><label>Business phone<input name="company_phone" value="${esc(state.settings.company_phone||'')}" maxlength="100"></label><button class="primary">Save company</button></form><h2>Database backup</h2><p class="muted small">Includes the ledger, original imports, attachments, corrections and audit history. Keep a copy outside this computer.</p><a href="/api/backup">Download complete database backup</a><details><summary>Restore a backup</summary><p class="small muted">Close the app first. From this app folder run the command below, then start normally. The existing database is preserved before restoring.</p><pre>python run.py --restore "path/to/backwoods-accounting-backup.sqlite3"</pre></details></section><section class="panel"><h2>Close an accounting period</h2><p class="muted small">Changes affecting closed dates will be rejected. Back up and finish reconciliation before closing. Reopening is not offered in this version.</p><p>Closed through: <strong>${esc(state.settings.closed_through||'No closed periods')}</strong></p><form id="close-form"><label>Close through date<input name="closed_through" type="date" required></label><label><input name="confirmed" type="checkbox" required>I have reviewed and backed up this period.</label><button>Close period</button></form></section></div><section class="panel"><h2>Audit history</h2>${state.audit.length?table(['Time (UTC)','Action','Details'],state.audit.map(a=>`<tr><td>${esc(a.at.slice(0,19).replace('T',' '))}</td><td>${esc(a.action)}</td><td class="small">${esc(a.detail)}</td></tr>`).join('')):empty('Audit history is empty','Imports and accounting changes will be recorded here.')}</section>`;}
async function load(){const query=new URLSearchParams({start,end});[state,rows]=await Promise.all([api('/api/state?'+query),api('/api/ledger?'+query)]);$('#company-name').textContent=state.settings.company;$('.avatar').textContent=state.user.name.split(' ').map(s=>s[0]).slice(0,2).join('').toUpperCase();$('.breadcrumb').firstChild.textContent=state.settings.company+' ';render();}
function render(){renderNavIcons();content.innerHTML=({overview,transactions,invoices:()=>docsPage('invoices'),bills:()=>docsPage('bills'),reports,accounts,imports,reconcile,settings,costing,pricing,inventory,assets,payroll,taxes,printing}[view]||overview)();$('#view-label').textContent=labels[view];document.body.dataset.role=state.user.role;document.querySelectorAll('.bar-fill[data-width]').forEach(b=>{b.style.width=b.dataset.width+'%';});document.querySelectorAll('nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function openDialog(html){$('#detail-content').innerHTML=html;$('#detail').showModal();}
function closeDialog(){$('#detail').close();}
function journalRow(){return `<div class="journal-row"><select name="account" aria-label="Account">${options()}</select><input type="number" name="debit" step="0.01" min="0" value="0" aria-label="Debit"><input type="number" name="credit" step="0.01" min="0" value="0" aria-label="Credit"></div>`;}
function journalDialog(){openDialog(`<h2>New company journal</h2><p class="small muted">Use balanced entries for opening balances, deposits, fees and corrections. Amounts are USD.</p><form id="journal-form"><div class="form-grid"><label>Date<input type="date" name="date" value="${today()}" required></label><label>Reference<input name="reference"></label></div><label>Memo<input name="memo" required></label><div class="journal-row small muted"><span>Account</span><span>Debit</span><span>Credit</span></div><div id="journal-lines">${journalRow()}${journalRow()}</div><button type="button" data-action="add-line">+ Add line</button><p id="journal-difference" class="small muted"></p><button class="primary">Post journal</button></form>`);}
function documentDialog(kind='invoice'){openDialog(`<h2>New business transaction</h2><p class="small muted">Use this for records entered directly into Business Accounting. Do not re-enter transactions already in either source app.</p><form id="manual-document-form"><div class="form-grid"><label>Type<select name="kind">${['invoice','bill','expense'].map(k=>`<option ${k===kind?'selected':''}>${k}</option>`).join('')}</select></label><label>Date<input type="date" name="date" value="${today()}" required></label><label>Customer / supplier<input name="party" required></label><label>Reference<input name="reference" required></label><label>Due date (invoice or bill)<input name="dueDate" type="date"></label><label>Subtotal / amount<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Sales tax (invoice only)<input name="tax" type="number" min="0" step="0.01" value="0"></label><label class="full">Revenue or expense / inventory account<select name="account">${options(null,kind==='invoice'?'4000':'5100')}</select></label><label class="full">Memo<textarea name="memo"></textarea></label></div><button class="primary">Save & post</button></form>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-view]');if(!b)return;try{if(b.dataset.view){view=b.dataset.view;pendingImport=null;$('#notice').hidden=true;await load();return;}switch(b.dataset.action){case 'register-asset':assetDialog();break;case 'asset-schedule':assetScheduleDialog(b.dataset.id);break;case 'depreciate':depreciationDialog(b.dataset.id);break;case 'dispose-asset':disposalDialog(b.dataset.id);break;case 'employee':employeeDialog();break;case 'local-payroll':localPayrollDialog();break;case 'pay-wages':payWagesDialog(b.dataset.id);break;case 'provider-connect':providerDialog();break;case 'provider-flow':await openProviderFlow(b.dataset.kind);break;case 'provider-sync':{const result=await api('/api/provider/sync',{});await load();notice(`Payroll sync: ${result.added} posted, ${result.duplicates} duplicates, ${result.issues.length} need accounting review.`);break;}case 'provider-stubs':providerStubsDialog(b.dataset.id);break;case 'provider-review':await providerReviewDialog(b.dataset.id);break;case 'provider-calculate':await api('/api/provider/calculate',{payrollId:b.dataset.id});notice('Calculation requested. Wait for the provider, then review the payroll.');break;case 'tax-check':notice((await api('/api/tax-watch/check',{})).message);break;case 'tax-review':taxReviewDialog(b.dataset.id);break;case 'tax-payment':taxPaymentDialog();break;case 'logout':await api('/api/auth/logout',{});state=null;await boot();return;case 'add-user':userDialog();break;case 'change-password':passwordDialog();break;case 'reset-filters':start=end=source='';await load();break;case 'new-document':documentDialog(b.dataset.kind);break;case 'journal':journalDialog();break;case 'add-line':$('#journal-lines').insertAdjacentHTML('beforeend',journalRow());break;case 'print':window.print();break;case 'add-component':$('#cost-components').insertAdjacentHTML('beforeend',componentRow());break;case 'edit-recipe':costingRecipeId=b.dataset.id;render();break;case 'new-recipe':costingRecipeId='';render();break;case 'save-recipe':await submitCosting(true);break;case 'save-pricing':await submitPricing(true);break;case 'edit-pricing':pricingId=b.dataset.id;render();break;case 'new-pricing':pricingId='';render();break;case 'void-record':if(confirm('Void this business-accounting record? Its posting will be reversed and its history retained.')){await api('/api/void',{id:b.dataset.id});closeDialog();await load();notice('Business record voided; its history was retained.');}break;case 'item-plan':itemPlanDialog(b.dataset.source,b.dataset.id);break;case 'commit-import':if(!pendingImport)throw Error('Preview the file first');b.disabled=true;const result=await api('/api/import',pendingImport);pendingImport=null;await load();notice(`Imported ${result.added} new records, revised ${result.changed}, skipped ${result.duplicates} duplicates.${result.reviewCount?' Historical inventory costs need review.':''}`);break;case 'document':{const d=await api('/api/document?'+new URLSearchParams({source:b.dataset.source,id:b.dataset.id}));const attachments=state.attachments.filter(a=>a.source===b.dataset.source&&a.source_id===b.dataset.id);openDialog(`<h2>${esc(d.reference)}</h2><p><a href="/print?type=record&source=${encodeURIComponent(b.dataset.source)}&id=${encodeURIComponent(b.dataset.id)}" target="_blank" rel="noopener">Print this record / save PDF</a></p><p>${badge(b.dataset.source)} · ${esc(d.date)} · Revision history remains in the company ledger</p>${d.lines.length?table(['Account','Debit','Credit'],d.lines.map(l=>`<tr><td>${esc(l.account)}</td><td class="amount">${currency(l.debit)}</td><td class="amount">${currency(l.credit)}</td></tr>`).join('')):'<p class="muted">Supporting or review record · no journal posted</p>'}${b.dataset.source==='manual'&&['invoice','bill','expense','journal'].includes(d.kind)?`<p><button class="danger" data-action="void-record" data-id="${esc(b.dataset.id)}">Void business record</button></p>`:''}<h3>Supporting files</h3>${attachments.map(a=>`<p><a href="/api/attachment?id=${encodeURIComponent(a.id)}">${esc(a.name)}</a></p>`).join('')}<form id="attachment-form" data-source="${esc(b.dataset.source)}" data-id="${esc(b.dataset.id)}"><label>Add receipt or invoice (up to 10 MB)<input name="file" type="file" required></label><button>Add attachment</button></form><details><summary>Original source record</summary><pre>${esc(JSON.stringify(d.original||d,null,2))}</pre></details>`);break;}case 'pay':{const d=state.documents.find(d=>d.source===(b.dataset.source||'manual')&&d.source_id===b.dataset.id);openDialog(`<h2>Payment · ${esc(d.reference)}</h2><p>Outstanding ${currency(d.balance)}</p><form id="pay-form"><input type="hidden" name="source" value="${esc(d.source)}"><input type="hidden" name="paymentId" value="${crypto.randomUUID()}"><input type="hidden" name="id" value="${esc(d.source_id)}"><label>Date<input name="date" type="date" value="${today()}" required></label><label>Amount<input name="amount" type="number" step="0.01" min="0.01" max="${d.balance/100}" value="${(d.balance/100).toFixed(2)}" required></label><label>Payment account<select name="account">${state.accounts.filter(a=>['1010','1020','1030'].includes(a.code)).map(a=>`<option value="${a.code}" ${a.code==='1020'?'selected':''}>${a.code} · ${esc(a.name)}</option>`).join('')}</select></label><button class="primary">Record payment</button></form>`);break;}case 'cost':openDialog(`<h2>Historical inventory cost</h2><p class="small muted">Enter the actual unit cost at the time of movement ${esc(b.dataset.id)}. This correction is saved and reused on subsequent imports.</p><form id="cost-form"><input type="hidden" name="id" value="${esc(b.dataset.id)}"><label>Unit cost (USD)<input name="unitCost" type="number" step="0.000001" min="0" required></label><button class="primary">Save cost & post</button></form>`);break;case 'account':openDialog(`<h2>Add account</h2><form id="account-form"><label>Code (4–6 digits)<input name="code" pattern="[0-9]{4,6}" required></label><label>Name<input name="name" required></label><label>Type<select name="type">${['asset','liability','equity','income','expense'].map(t=>`<option>${t}</option>`).join('')}</select></label><button class="primary">Add account</button></form>`);break;}}catch(err){notice(err.message,true);b.disabled=false;}});
$('#refresh').onclick=()=>load().catch(e=>notice(e.message,true));
document.addEventListener('submit',async e=>{const form=e.target;if(form.method==='dialog')return;e.preventDefault();const button=form.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;try{const v=formValue(form);switch(form.getAttribute('id')){case 'asset-form':v.postPurchase=form.elements.postPurchase.checked;await api('/api/assets/register',v);break;case 'depreciate-form':await api('/api/assets/depreciate',v);break;case 'dispose-form':await api('/api/assets/dispose',v);break;case 'employee-form':await api('/api/employees',v);break;case 'local-payroll-form':v.paid=form.elements.paid.checked;await api('/api/payroll/post',v);break;case 'wages-form':await api('/api/payroll/pay',v);break;case 'provider-form':await api('/api/provider/connect',v);break;case 'provider-submit-form':await api('/api/provider/submit',v);notice('Payroll submitted to the provider. Processing and deposit settlement are pending.');break;case 'tax-states-form':await api('/api/tax-watch/configure',{states:[...form.querySelectorAll('[name=state]:checked')].map(c=>c.value)});break;case 'tax-review-form':await api('/api/tax-watch/review',v);break;case 'tax-payment-form':await api('/api/liability-payment',v);break;case 'login-form':await submitLogin(form);return;case 'user-form':await api('/api/users',v);break;case 'password-form':await api('/api/auth/password',v);closeDialog();state=null;await boot();notice('Password changed. Sign in again.');return;case 'pricing-form':await submitPricing(false);return;case 'item-plan-form':await api('/api/item-plan',v);break;case 'costing-form':await submitCosting(false);return;case 'filters':if(v.start&&v.end&&v.start>v.end)throw Error('Start date must be before the end date');start=v.start;end=v.end;if(v.source!==undefined)source=v.source;await load();return;case 'import-form':{const file=form.elements.file.files[0];if(!file)throw Error('Choose a backup');if(file.size>40*1024*1024)throw Error('Backup exceeds 40 MB');pendingImport=null;const candidate={source:v.source,filename:file.name,payload:JSON.parse(await file.text())};const r=await api('/api/import/preview',candidate);pendingImport=candidate;$('#import-preview').innerHTML=`<div class="banner"><div><strong>Preview: ${r.added} new · ${r.changed} revised · ${r.duplicates} duplicates</strong><p>${r.records} source records checked. No changes committed yet.</p></div></div>${r.warnings.map(w=>`<p class="small muted">${esc(w)}</p>`).join('')}<button class="primary" data-action="commit-import">Import into company ledger</button>`;return;}case 'journal-form':v.lines=[...form.querySelectorAll('.journal-row')].filter(r=>r.querySelector('select')).map(r=>({account:r.querySelector('select').value,debit:r.querySelector('[name=debit]').value,credit:r.querySelector('[name=credit]').value})).filter(l=>Number(l.debit)||Number(l.credit));await api('/api/journal',v);break;case 'manual-document-form':await api('/api/manual-document',v);break;case 'pay-form':await api('/api/pay',v);break;case 'account-form':await api('/api/account',v);break;case 'cost-form':await api('/api/cost',v);break;case 'company-form':await api('/api/settings',v);break;case 'close-form':await api('/api/settings',{closed_through:v.closed_through});break;case 'attachment-form':{const file=form.elements.file.files[0];if(!file||file.size>10*1024*1024)throw Error('Choose a file of 10 MB or less');const bytes=new Uint8Array(await file.arrayBuffer());let text='';for(let i=0;i<bytes.length;i+=8192)text+=String.fromCharCode(...bytes.subarray(i,i+8192));await api('/api/attachment',{source:form.dataset.source,sourceId:form.dataset.id,name:file.name,content:btoa(text)});break;}case 'reconcile-form':await api('/api/reconcile',{...v,lineIds:[...form.querySelectorAll('[name=line]:checked')].map(c=>Number(c.value)),statement:statementRows});break;default:return;}closeDialog();await load();notice('Saved to your company books.');}catch(err){notice(err.message,true);}finally{if(button)button.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.id==='ledger-search'){search=e.target.value;const pos=e.target.selectionStart;render();$('#ledger-search').focus();$('#ledger-search').setSelectionRange(pos,pos);}if(e.target.closest('#reconcile-form')){const f=$('#reconcile-form');const actual=Math.round(Number(f.elements.starting.value)*100)+[...f.querySelectorAll('[name=line]:checked')].reduce((s,c)=>s+Number(c.dataset.amount),0);$('#reconcile-difference').textContent=currency(Math.round(Number(f.elements.ending.value)*100)-actual);}if(e.target.closest('#journal-form')){let d=0,c=0;for(const r of document.querySelectorAll('#journal-lines .journal-row')){d+=Math.round(Number(r.querySelector('[name=debit]').value)*100);c+=Math.round(Number(r.querySelector('[name=credit]').value)*100);}$('#journal-difference').textContent=`Debits ${currency(d)} · Credits ${currency(c)} · Difference ${currency(d-c)}`;}});
let statementRows=[];
function parseCSV(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>x.trim()))rows.push(row);row=[];field='';}else field+=c;}if(quoted)throw Error('Unclosed quote in CSV');row.push(field);if(row.some(x=>x.trim()))rows.push(row);return rows;}
document.addEventListener('change',async e=>{if(e.target.closest('#import-form')){pendingImport=null;$('#import-preview').innerHTML='';}if(e.target.id!=='statement-file')return;try{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Statement exceeds 5 MB');const parsed=parseCSV((await file.text()).replace(/^\uFEFF/,''));const heads=parsed.shift()?.map(h=>h.toLowerCase().trim());const indexes=['date','description','amount'].map(h=>heads?.indexOf(h));if(indexes.some(i=>i<0))throw Error('CSV requires date, description and amount columns');statementRows=parsed.map(r=>({date:r[indexes[0]],description:r[indexes[1]],amount:r[indexes[2]]}));if(statementRows.some(r=>!r.date||!r.amount||!Number.isFinite(Number(r.amount))))throw Error('Every statement row needs a date and numeric signed amount');let matched=0;const used=new Set();for(const r of statementRows){const amount=Math.round(Number(r.amount)*100);const choices=[...document.querySelectorAll('#reconcile-form [name=line]')].filter(c=>Number(c.dataset.amount)===amount&&!used.has(c.value));if(choices.length===1){choices[0].checked=true;used.add(choices[0].value);matched++;}}$('#statement-result').innerHTML=`<p class="small">${statementRows.length} statement rows · ${matched} unique amount matches selected. Verify each match.</p>`;$('#reconcile-form').dispatchEvent(new Event('input',{bubbles:true}));}catch(err){notice(err.message,true);}});
boot().catch(err=>notice(err.message,true));
// Feed polling updates the connection indicator without replacing an active form.
refreshTimer=setInterval(async()=>{if(!state||view!=='overview'||$('#detail').open||document.activeElement?.tagName==='INPUT')return;try{await load();}catch{}},15000);

function componentRow(row={}){return `<div class="cost-component"><input name="componentName" placeholder="Ingredient or packaging" aria-label="Component name" value="${esc(row.name||'')}"><select name="componentKind" aria-label="Component kind"><option value="ingredient">Ingredient</option><option value="packaging" ${row.kind==='packaging'?'selected':''}>Packaging</option></select><input name="componentQuantity" type="number" step="0.000001" min="0" placeholder="Quantity" aria-label="Component quantity" value="${esc(row.quantity??'')}"><input name="componentUnit" placeholder="lb, oz, each…" aria-label="Component unit" value="${esc(row.unit||'')}"><input name="componentCost" type="number" min="0" step="0.000001" placeholder="Cost per unit" aria-label="Component unit cost" value="${esc(row.unitCost??'')}"></div>`;}
function costing(){const saved=state.recipes.find(r=>r.id===costingRecipeId);const p=saved?.payload||{};const numeric=(name,label,def=0,step='0.01')=>`<label>${label}<input name="${name}" type="number" min="0" step="${step}" value="${esc(p[name]??def)}" required></label>`;return title('Know what it costs to make.','Build recipes, compare prices and calculate the real cost of each sellable unit.',`<button data-action="new-recipe">+ New recipe</button>`)+`<div class="banner"><span>⚗</span><div><strong>Plan production without changing your books.</strong><p>Saved recipes are estimates. They do not create expenses, change inventory, or overwrite source-app costs. Record actual purchases, payroll and production journals separately.</p></div></div><div class="two-col"><section class="panel"><h2>${saved?'Edit saved recipe':'Build a production cost'}</h2><form id="costing-form"><label>Product / recipe name<input name="name" value="${esc(p.name||'')}" placeholder="e.g. Root beer · 100 bottle batch" required></label><div class="form-grid">${numeric('yieldUnits','Expected units per batch',100,'0.001')}${numeric('wastePercent','Expected waste / spoilage %',0,'0.01')}</div><h3>Ingredients & packaging</h3><p class="small muted">Quantity and cost must use the same unit. For 2 lb at $4 per lb, enter quantity 2, unit lb, cost 4. Leave unused rows blank.</p><div class="cost-component component-head"><span>Component</span><span>Type</span><span>Quantity</span><span>Unit</span><span>Cost / unit ($)</span></div><div id="cost-components">${(p.materials?.length?p.materials:[{},{}]).map(componentRow).join('')}</div><button type="button" data-action="add-component">+ Add component</button><h3 class="spaced">Labor & overhead per batch</h3><div class="form-grid">${numeric('laborHours','Total labor hours',0,'0.001')}${numeric('laborRate','Labor cost per hour ($)')}${numeric('laborBurdenPercent','Payroll taxes / benefits %')}${numeric('overhead','Allocated batch overhead ($)')}${numeric('otherCost','Other batch costs ($)')}${numeric('targetMargin','Target gross margin %',40)}${numeric('sellingPrice','Planned selling price per unit ($)')}</div><label>Notes<textarea name="notes" placeholder="Yield assumptions, supplier quotes, equipment costs…">${esc(p.notes||'')}</textarea></label><div class="actions"><button class="primary">Calculate production cost</button><button type="button" data-action="save-recipe">Save recipe & costs</button></div></form><div id="costing-result">${saved?costingResult(saved.result):''}</div></section><section class="panel"><h2>Saved product costs</h2><p class="small muted">Reopen a recipe to update supplier costs, labor rates or batch size.</p>${state.recipes.length?state.recipes.map(r=>`<div class="connection"><strong>${esc(r.name)}</strong><div class="health-row"><span>Cost per sellable unit</span><strong>${currency(r.result.unitCost)}</strong></div><div class="health-row"><span>Suggested selling price</span><strong>${currency(r.result.suggestedPrice)}</strong></div><small>Updated ${esc(r.updated_at.slice(0,10))}</small><button data-action="edit-recipe" data-id="${esc(r.id)}">Open recipe</button></div>`).join(''):empty('No saved recipes yet','Calculate your first batch and save it for next time.')}<h3>Included in your calculation</h3><ul class="instructions"><li>Ingredients and packaging quantities multiplied by their unit costs.</li><li>Labor hours × hourly cost, plus your payroll burden percentage.</li><li>Batch overhead and other production costs.</li><li>Waste reduces sellable units and increases cost per sellable unit.</li><li>Suggested price = unit cost ÷ (1 − target margin). Margin and markup are different.</li></ul></section></div>`;}
function costingResult(r){return `<div class="cards cost-cards"><div class="card"><div class="card-label">Total batch cost</div><strong>${currency(r.total)}</strong><small>${r.sellableUnits.toLocaleString()} sellable units</small></div><div class="card featured"><div class="card-label">Cost / sellable unit</div><strong>${currency(r.unitCost)}</strong><small>Precise cost: $${r.unitCostPrecise.toFixed(4)}</small></div><div class="card"><div class="card-label">Suggested unit price</div><strong>${currency(r.suggestedPrice)}</strong><small>At ${r.targetMargin}% target margin</small></div></div>${table(['Cost component','Amount'],[['Ingredients',r.ingredients],['Packaging',r.packaging],['Labor including burden',r.labor],['Allocated overhead',r.overhead],['Other production costs',r.other]].map(([n,v])=>`<tr><td>${n}</td><td class="amount">${currency(v)}</td></tr>`).join(''))}<div class="health-row"><span>Profit per unit at your selling price</span><strong>${currency(r.unitProfit)}</strong></div><div class="health-row"><span>Gross margin / markup</span><strong>${r.grossMargin===null?'—':r.grossMargin.toFixed(2)+'%'} / ${r.markup===null?'—':r.markup.toFixed(2)+'%'}</strong></div><div class="report-total"><span>Estimated profit per batch</span><span>${currency(r.estimatedBatchProfit)}</span></div>`;}
async function submitCosting(save){const form=$('#costing-form');if(!form.reportValidity())return;const v=formValue(form);v.materials=[...form.querySelectorAll('.cost-component')].filter(row=>row.querySelector('input')).map(row=>({name:row.querySelector('[name=componentName]').value,kind:row.querySelector('[name=componentKind]').value,quantity:row.querySelector('[name=componentQuantity]').value||0,unit:row.querySelector('[name=componentUnit]').value,unitCost:row.querySelector('[name=componentCost]').value||0})).filter(r=>r.name||Number(r.quantity)||Number(r.unitCost));if(costingRecipeId)v.id=costingRecipeId;const result=await api('/api/costing/'+(save?'save':'calculate'),v);if(save){costingRecipeId=result.id;await load();notice('Production recipe saved. The company ledger was not changed.');}$('#costing-result').innerHTML=costingResult(result);}

function agingPanel(invoices){const list=state.aging.filter(a=>invoices?['invoice','support-invoices'].includes(a.kind):['bill','support-bills'].includes(a.kind));return `<section class="panel"><h2>${invoices?'Customer receivables':'Supplier payables'} · current aging</h2><p class="small muted">Current outstanding balances, not a historical aging reconstruction. Missing due dates are shown explicitly.</p>${list.length?table(['Customer / supplier','Reference','Due date','Status','Balance'],list.map(a=>`<tr><td>${esc(a.party||'—')}</td><td>${esc(a.reference)}</td><td>${esc(a.dueDate||'Not supplied')}</td><td><span class="badge ${a.daysOverdue>0?'warn':''}">${a.daysOverdue===null?'Due date needed':a.daysOverdue>0?a.daysOverdue+' days overdue':'Current'}</span></td><td class="amount">${currency(a.balance)}</td></tr>`).join('')):empty('No outstanding balances','Unpaid invoices and bills appear here.')}</section>`;}
function inventory(){return title('Keep shelves and deliveries supplied.','Read-only source inventory, with reorder and shelf-life planning kept in Business Accounting.')+`<div class="banner warning"><div><strong>Source stock is shown separately for accuracy.</strong><p>Both apps may refer to the same physical inventory. Quantities are not added together automatically. Reorder plans and expiry notes do not change source stock or post accounting entries.</p></div></div><section class="panel"><h2>Stock & replenishment</h2>${state.catalog.length?table(['Item / SKU','Stock source','Location','On hand / available','Reorder plan','Shelf life / expiry',''],state.catalog.map(p=>{const avail=p.onHand-p.reserved;const point=Number(p.plan.reorderPoint??p.reorderLevel);const target=Number(p.plan.targetStock??point);const reorder=avail<=point;return `<tr><td><strong>${esc(p.name)}</strong><div class="small muted">${esc(p.sku||p.id)} · ${esc(p.unit)} · ${p.caseQty} / case</div></td><td>${badge(p.source)}</td><td>${esc(p.location)}</td><td>${p.onHand} / ${avail}</td><td>${reorder?`<span class="badge warn">${Math.max(0,target-avail)} units suggested</span>`:'<span class="badge">Stock above reorder point</span>'}<div class="small muted">Point ${point} · lead ${Number(p.plan.leadTimeDays||0)} days</div></td><td>${p.plan.shelfLifeDays?Number(p.plan.shelfLifeDays)+' days':'—'}<div class="small ${p.plan.expiryDate&&p.plan.expiryDate<today()?'amount-negative':'muted'}">${esc(p.plan.expiryDate||'No expiry recorded')}</div></td><td><button data-action="item-plan" data-source="${esc(p.source)}" data-id="${esc(p.id)}">Plan</button></td></tr>`;}).join('')):empty('Import source inventory to start planning','The connected main app sends inventory rows; Vendor Ordering sends its product stock.')}</section><section class="panel"><h2>Store sales & consignment</h2><ul class="instructions"><li><strong>Retail counter sales:</strong> record sales and refunds in the main app; its ledger feeds the company books.</li><li><strong>Wholesale delivery:</strong> Vendor Ordering feeds delivered invoices, taxes, payments, returns and captured costs.</li><li><strong>Consignment:</strong> delivery to a store is a stock transfer, not a customer sale. Do not create a delivered wholesale invoice for consigned stock. Track store sell-through and record sales only when earned.</li><li><strong>Shared stock:</strong> transfers between warehouse and your own retail stores should move inventory without creating company revenue.</li><li><strong>Lots and expiry:</strong> use source lot records and keep planning notes here. This screen is a replenishment planner, not a full lot-traceability or recall system.</li></ul></section>`;}
function itemPlanDialog(source,id){const p=state.catalog.find(p=>p.source===source&&p.id===id);if(!p)throw Error('Item not found');const v=p.plan;openDialog(`<h2>Inventory plan · ${esc(p.name)}</h2><p class="small muted">This planning record does not change stock or source-app settings.</p><form id="item-plan-form"><input type="hidden" name="source" value="${esc(source)}"><input type="hidden" name="id" value="${esc(id)}"><div class="form-grid">${[['reorderPoint','Reorder at available units',p.reorderLevel],['targetStock','Target units after replenishment',p.reorderLevel],['leadTimeDays','Supplier lead time (days)',0],['shelfLifeDays','Shelf life (days)',0]].map(([key,label,def])=>`<label>${label}<input type="number" min="0" step="0.01" name="${key}" value="${esc(v[key]??def)}" required></label>`).join('')}<label>Next expiry date<input name="expiryDate" type="date" value="${esc(v.expiryDate||'')}"></label><label>Location / lot note<input name="lotNote" value="${esc(v.lotNote||'')}"></label></div><button class="primary">Save inventory plan</button></form>`);}
function pricing(){const saved=state.pricing.find(p=>p.id===pricingId);const v=saved?.payload||{};const num=(key,label,def=0)=>`<label>${label}<input type="number" min="0" step="0.0001" name="${key}" value="${esc(v[key]??def)}" required></label>`;return title('Price for the way you sell.','Compare retail, wholesale and distributor margins, including case packs, delivery and selling fees.',`<button data-action="new-pricing">+ New price plan</button>`)+`<div class="two-col"><section class="panel"><h2>Product & channel economics</h2><form id="pricing-form"><label>Product name / SKU<input name="name" value="${esc(v.name||'')}" required></label><label>Use a saved production cost<select id="pricing-recipe"><option value="">Enter landed cost below</option>${state.recipes.map(r=>`<option value="${r.id}">${esc(r.name)} · ${currency(r.result.unitCost)} per unit</option>`).join('')}</select></label><div class="form-grid">${num('unitCost','Production / landed unit cost ($)')}${num('caseQty','Units per case',12)}${num('retailPrice','Retail selling price / unit ($)')}${num('wholesalePrice','Wholesale selling price / unit ($)')}${num('distributorPrice','Distributor price / unit ($)')}${num('deliveryPerCase','Delivery cost / case ($)')}${num('retailFeePercent','Retail selling / card fees %')}${num('wholesaleFeePercent','Wholesale selling fees %')}${num('targetMargin','Target contribution margin %',35)}</div><p class="small muted">Prices exclude sales tax. Include purchased-product freight in landed unit cost; enter outbound delivery cost per case separately.</p><div class="actions"><button class="primary">Calculate channel margins</button><button type="button" data-action="save-pricing">Save price plan</button></div></form><div id="pricing-result">${saved?pricingResult(saved.result):''}</div></section><section class="panel"><h2>Saved price plans</h2>${state.pricing.length?state.pricing.map(p=>`<div class="connection"><strong>${esc(p.name)}</strong><small>${p.result.caseQty} units / case · base case cost ${currency(p.result.caseCost)}</small><button data-action="edit-pricing" data-id="${esc(p.id)}">Open plan</button></div>`).join(''):empty('No saved price plans','Save separate scenarios for store shelves, wholesale accounts and distributors.')}<h3>Before selling through stores</h3><ul class="instructions"><li>Agree on case size, minimum orders, delivery fees, payment terms and returns policy.</li><li>Compare retailer shelf margin with your wholesale margin.</li><li>Track damage, expirations and promotional credits against the original invoice.</li><li>Keep sales tax collected separate from revenue. Confirm resale / exemption handling in the source app.</li><li>These scenarios do not update source-app catalog prices automatically.</li></ul></section></div>`;}
function pricingResult(r){return `<h3 class="spaced">Channel comparison</h3>${table(['Channel','Unit price','Unit cost incl. fees','Unit profit','Margin','Case revenue','Suggested unit price'],r.channels.map(c=>`<tr><td>${esc(c.name)} ${c.belowCost?'<span class="badge warn">Below cost</span>':''}</td><td class="amount">${currency(c.price)}</td><td class="amount">${currency(c.cost)}</td><td class="amount">${currency(c.profit)}</td><td>${c.margin===null?'—':c.margin.toFixed(2)+'%'}</td><td class="amount">${currency(c.caseRevenue)}</td><td class="amount">${c.suggestedPrice===null?'Not achievable with these fees':currency(c.suggestedPrice)}</td></tr>`).join(''))}<div class="health-row"><span>Retailer's shelf margin at your wholesale price</span><strong>${r.retailerMargin===null?'—':r.retailerMargin.toFixed(2)+'%'}</strong></div><p class="small muted">Contribution margins include the entered fees and delivery cost, and exclude any overhead not already included in unit cost.</p>`;}
async function submitPricing(save){const form=$('#pricing-form');if(!form.reportValidity())return;const v=formValue(form);if(pricingId)v.id=pricingId;const result=await api('/api/pricing/'+(save?'save':'calculate'),v);if(save){pricingId=result.id;await load();notice('Channel pricing plan saved. Source-app prices were not changed.');}$('#pricing-result').innerHTML=pricingResult(result);}
document.addEventListener('change',e=>{if(e.target.id==='pricing-recipe'&&e.target.value){const recipe=state.recipes.find(r=>r.id===e.target.value);$('#pricing-form [name=unitCost]').value=recipe.result.unitCostPrecise.toFixed(6);if(!$('#pricing-form [name=name]').value)$('#pricing-form [name=name]').value=recipe.name;}if(e.target.matches('#manual-document-form [name=kind]')){const k=e.target.value;$('#manual-document-form [name=account]').value=k==='invoice'?'4000':'5100';}});

async function boot(){const auth=await api('/api/auth/status');if(auth.user){document.body.classList.remove('signed-out');$('#login-screen')?.remove();await load();return;}state=null;rows=[];pendingImport=null;content.innerHTML='';$('#detail-content').innerHTML='';if($('#detail').open)$('#detail').close();document.body.classList.add('signed-out');let screen=$('#login-screen');if(!screen){screen=document.createElement('section');screen.id='login-screen';document.body.append(screen);}screen.innerHTML=`<div class="login-card"><div class="eyebrow">BACKWOODS BUSINESS ACCOUNTING</div><h1>${auth.initialized?'Welcome back.':'Your business starts here.'}</h1><p class="muted">${auth.initialized?'Sign in to your company books.':'Create the owner account. No default password is installed.'}</p><form id="login-form" data-setup="${auth.initialized?'no':'yes'}">${auth.initialized?'':'<label>Your name<input name="name" autocomplete="name" required></label>'}<label>Username or email<input name="username" autocomplete="username" required maxlength="100"></label><label>Password<input type="password" name="password" autocomplete="${auth.initialized?'current-password':'new-password'}" minlength="${auth.initialized?'1':'12'}" maxlength="256" required></label>${auth.initialized?'':'<label>Confirm password<input type="password" name="confirmPassword" autocomplete="new-password" minlength="12" maxlength="256" required></label><p class="small muted">Use a passphrase of at least 12 characters. Keep a database backup and your password in a safe place.</p>'}<button class="primary">${auth.initialized?'Sign in':'Create owner account'}</button><p id="login-error" role="alert" class="amount-negative"></p></form><p class="small muted">Stored on this computer · Protected by your local account</p></div>`;}
async function submitLogin(form){const v=formValue(form);try{if(form.dataset.setup==='yes'&&v.password!==v.confirmPassword)throw Error('The passwords do not match');await api('/api/auth/'+(form.dataset.setup==='yes'?'setup':'login'),v);await boot();}catch(e){$('#login-error').textContent=e.message;}}
function settings(){return baseSettings()+`<section class="panel"><div class="panel-head"><h2>Your account</h2><button data-action="logout">Sign out</button></div><p>Signed in as <strong>${esc(state.user.name)}</strong> · ${esc(state.user.role)}</p><button data-action="change-password">Change password</button>${state.user.role==='owner'?`<h3 class="spaced">Company users</h3>${table(['Name','Username','Access'],state.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.username)}</td><td>${esc(u.role)}</td></tr>`).join(''))}<button data-action="add-user">+ Add user</button>`:''}</section>`;}
function userDialog(){openDialog(`<h2>Add company user</h2><form id="user-form"><label>Name<input name="name" required></label><label>Username or email<input name="username" required autocomplete="off"></label><label>Initial password<input name="password" type="password" minlength="12" maxlength="256" autocomplete="new-password" required></label><label>Access<select name="role"><option value="viewer">Read-only financial viewer</option><option value="accountant">Accountant · bookkeeping & payroll</option><option value="owner">Owner · all settings and user management</option></select></label><button class="primary">Create user</button></form>`);}
function passwordDialog(){openDialog(`<h2>Change your password</h2><p class="small muted">This signs out your existing sessions.</p><form id="password-form"><label>Current password<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>New password<input name="newPassword" type="password" minlength="12" maxlength="256" autocomplete="new-password" required></label><button class="primary">Change password</button></form>`);}

function assets(){const list=state.assets;return title('Equipment that stays on the books.','Register equipment, post monthly book depreciation, and track disposals.',`<a href="/print?type=assets" target="_blank" rel="noopener">Print asset register</a><button class="primary" data-action="register-asset">+ Register equipment</button>`)+`<div class="cards"><div class="card"><div class="card-label">Equipment cost</div><strong>${currency(list.filter(a=>!a.disposedAt).reduce((s,a)=>s+a.cost,0))}</strong></div><div class="card"><div class="card-label">Accumulated depreciation</div><strong>${currency(list.filter(a=>!a.disposedAt).reduce((s,a)=>s+a.accumulated,0))}</strong></div><div class="card featured"><div class="card-label">Net book value</div><strong>${currency(list.filter(a=>!a.disposedAt).reduce((s,a)=>s+a.bookValue,0))}</strong></div><div class="card"><div class="card-label">Registered assets</div><strong>${list.length}</strong></div></div><div class="banner"><div><strong>Book depreciation · straight line, full-month convention.</strong><p>Cost less salvage is allocated over your selected useful life, starting in the selected month. Tax depreciation, Section 179 and bonus depreciation require separate tax treatment. Previously recorded depreciation needs a reviewed migration before registering an older asset.</p></div></div><section class="panel">${list.length?table(['Equipment','Purchased','Cost','Accumulated depreciation','Net book value',''],list.map(a=>`<tr><td><strong>${esc(a.name)}</strong><div class="small muted">${esc(a.location)} ${a.disposedAt?'· Disposed '+esc(a.disposedAt):''}</div></td><td>${esc(a.purchaseDate)}</td><td class="amount">${currency(a.cost)}</td><td class="amount">${currency(a.accumulated)}</td><td class="amount">${currency(a.bookValue)}</td><td><button data-action="asset-schedule" data-id="${a.id}">Schedule</button> ${a.disposedAt?'':`<button data-action="depreciate" data-id="${a.id}">Post depreciation</button>`}</td></tr>`).join('')):empty('No equipment registered','Register a purchase or link equipment already recorded in Fixed Assets.')}</section>`;}
function assetDialog(){const linked=state.documents.filter(d=>rows.some(r=>r.source===d.source&&r.source_id===d.source_id&&r.account==='1500'&&r.debit>0));openDialog(`<h2>Register equipment</h2><form id="asset-form"><div class="form-grid"><label>Equipment name<input name="name" required></label><label>Purchase date<input name="purchaseDate" type="date" value="${today()}" required></label><label>Total cost ($)<input name="cost" type="number" min="0.01" step="0.01" required></label><label>Salvage / residual value ($)<input name="salvage" type="number" min="0" step="0.01" value="0" required></label><label>Useful life (months)<input name="lifeMonths" type="number" min="1" max="600" value="60" required></label><label>First full depreciation month<input name="startMonth" type="month" value="${today().slice(0,7)}" required></label><label>Serial number<input name="serialNumber"></label><label>Location<input name="location"></label><label>Supplier<input name="supplier"></label><label>Purchase reference<input name="reference"></label></div><label><input name="postPurchase" type="checkbox" checked>Record this equipment purchase now</label><label>Paid / funded from<select name="fundingAccount">${state.accounts.filter(a=>['1010','1020','2000','2500','3000'].includes(a.code)).map(a=>`<option value="${a.code}" ${a.code==='1020'?'selected':''}>${a.code} · ${esc(a.name)}</option>`).join('')}</select></label><details><summary>Purchase already recorded?</summary><p class="small muted">Uncheck Record purchase, then choose an existing 1500 Fixed Assets transaction. This prevents counting the purchase twice.</p><label>Existing transaction<select name="linkedId"><option value="">Choose a recorded purchase</option>${linked.map(d=>`<option value="${esc(d.source_id)}" data-source="${d.source}">${esc(d.reference)} · ${currency(d.amount)}</option>`).join('')}</select></label><input name="linkedSource" type="hidden" value="manual"></details><label>Notes<textarea name="notes"></textarea></label><button class="primary">Register equipment</button></form>`);}
function assetScheduleDialog(id){const a=state.assets.find(a=>a.id===id);openDialog(`<h2>${esc(a.name)} · depreciation schedule</h2><p>Cost ${currency(a.cost)} · Residual ${currency(a.salvage)} · ${a.lifeMonths} months</p><p><a href="/print?type=asset&id=${id}" target="_blank" rel="noopener">Print schedule / save PDF</a></p>${table(['Month','Depreciation','Status'],a.schedule.map(r=>`<tr><td>${r.month}</td><td class="amount">${currency(r.amount)}</td><td>${r.posted?'Posted':'Scheduled'}</td></tr>`).join(''))}${a.disposedAt?'':`<p><button class="danger" data-action="dispose-asset" data-id="${id}">Record sale / disposal</button></p>`}`);}
function depreciationDialog(id){const a=state.assets.find(a=>a.id===id);const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-1);const month=d.toLocaleDateString('en-CA').slice(0,7);openDialog(`<h2>Post depreciation · ${esc(a.name)}</h2><p class="small muted">Only unposted, completed months are posted. Repeating a month cannot create another depreciation entry.</p><form id="depreciate-form"><input name="id" type="hidden" value="${id}"><label>Through month<input name="throughMonth" type="month" value="${month}" required></label><button class="primary">Post monthly depreciation</button></form>`);}
function disposalDialog(id){openDialog(`<h2>Record equipment disposal</h2><p class="small muted">The entry removes asset cost and accumulated depreciation, records proceeds, and recognizes the remaining gain or loss. Post any depreciation through disposal first.</p><form id="dispose-form"><input name="id" type="hidden" value="${id}"><label>Disposal date<input type="date" name="date" value="${today()}" required></label><label>Bank proceeds ($)<input name="proceeds" type="number" step="0.01" min="0" value="0" required></label><button class="primary">Record disposal</button></form>`);}
function payroll(){const connection=state.payrollConnection;const provider=state.providerPayrolls.payrolls;const local=state.payroll.filter(p=>p.source==='manual');return title('Payroll, managed with your business.','A connected payroll service handles state tax calculations and direct deposit. Your ledger keeps the accounting.',`<button data-action="provider-connect">${connection.connected?'Update connection':'Connect payroll service'}</button><button class="primary" data-action="provider-flow" data-kind="run-payroll" ${connection.connected?'':'disabled'}>Run payroll</button>`)+`<div class="banner ${connection.connected?'':'warning'}"><div><strong>${connection.connected?'Gusto connection configured · '+esc(connection.environment):'Payroll service not connected'}</strong><p>${connection.connected?'Provider account approval, employer setup, employee tax settings and bank verification determine live readiness. Demo mode never pays employees.':'Live 50-state payroll and direct deposit require an approved Gusto Embedded Payroll connection. No credentials or live payroll account are bundled with the app.'}</p></div></div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Connected payroll</h2><span class="badge ${connection.environment==='production'?'':'warn'}">${connection.environment==='production'?'Production':'Demo / not connected'}</span></div><div class="actions"><button data-action="provider-flow" data-kind="onboarding" ${connection.connected?'':'disabled'}>Employer & employee onboarding</button><button data-action="provider-sync" ${connection.connected?'':'disabled'}>Refresh payroll & sync books</button></div><p class="small muted spaced">Use the provider workflow to configure employees, state registrations, compensation, benefits, direct-deposit accounts and payroll hours. Review the calculated pay run before authorizing it. Processing is different from bank settlement.</p>${provider.length?table(['Pay date','Provider status','Gross','Net pay',''],provider.map(p=>{const id=p.payroll_uuid||p.uuid;return `<tr><td>${esc(p.check_date)}</td><td><span class="badge">${p.processed?'Processed':'Draft / unprocessed'}</span></td><td class="amount">${currency(Math.round(Number(p.totals?.gross_pay||0)*100))}</td><td class="amount">${currency(Math.round(Number(p.totals?.net_pay||0)*100))}</td><td>${p.processed?`<button data-action="provider-stubs" data-id="${id}">Pay stubs</button><div class="small muted">Confirm settlement at provider</div>`:`<button data-action="provider-calculate" data-id="${id}">Calculate</button> <button data-action="provider-review" data-id="${id}">Review</button>`}</td></tr>`;}).join('')):empty('No payroll results synced','Connect the provider, complete onboarding, and refresh payroll history.')}${state.providerPayrolls.issues.map(i=>`<div class="banner warning"><div><strong>Accounting review needed</strong><p>${esc(i.payrollId)} · ${esc(i.message)}</p></div></div>`).join('')}</section><section class="panel"><h2>Payroll checklist</h2><ul class="checklist"><li>Approved payroll-provider company account</li><li>Employer federal and state registrations</li><li>Employee onboarding and tax elections</li><li>Employee work locations and direct-deposit consent</li><li>Verified employer bank account and funding deadline</li><li>Review hours, overtime, tips, benefits and gross-to-net</li><li>Authorize the specific payroll, then confirm provider status</li><li>Reconcile payroll funding and tax settlements to the bank</li></ul><p class="small muted spaced">Your original main-app payroll is already included when its ledger is imported. Do not re-enter the same payroll here.</p></section></div><section class="panel"><div class="panel-head"><h2>Business payroll records</h2><div class="actions"><a href="/print?type=payroll" target="_blank" rel="noopener">Print payroll register</a><a href="/api/payroll.csv">Export CSV</a><button data-action="local-payroll">Record external payroll</button><button data-action="employee">+ Local employee</button></div></div><p class="small muted">Use external payroll entry only for payroll calculated outside this connection. It records accounting amounts and does not send a payment.</p>${local.length?table(['Pay date','Employee','Reference','Gross','Unpaid net wages',''],local.map(d=>`<tr><td>${d.date}</td><td>${esc(d.party)}</td><td>${esc(d.reference)}</td><td class="amount">${currency(d.amount)}</td><td class="amount">${currency(d.balance)}</td><td><a href="/print?type=paystub&id=${encodeURIComponent(d.id)}" target="_blank" rel="noopener">Pay stub</a> ${d.balance?`<button data-action="pay-wages" data-id="${esc(d.id)}">Record payment</button>`:''}</td></tr>`).join('')):empty('No directly entered payroll','Provider payroll and imported main-app payroll remain traceable to their sources.')}</section>`;}
function providerDialog(){openDialog(`<h2>Connect Gusto Embedded Payroll</h2><p class="small muted">Requires an approved Gusto developer / partner application and authorized company. This does not create a provider account. On Windows, connection secrets are protected with your Windows account. Never put secrets in source files or send them in chat.</p><form id="provider-form"><label>Environment<select name="environment"><option value="demo">Demo · no real payments</option><option value="production">Production · live payroll</option></select></label><label>Company UUID<input name="companyId" autocomplete="off" required></label><label>Company access token<input name="accessToken" type="password" autocomplete="off" required></label><details><summary>Authorization refresh settings</summary><label>Client ID<input name="clientId" autocomplete="off"></label><label>Client secret<input name="clientSecret" type="password" autocomplete="off"></label><label>Refresh token<input name="refreshToken" type="password" autocomplete="off"></label></details><button class="primary">Verify & save connection</button></form>`);}
async function openProviderFlow(kind){const response=await api('/api/provider/flow',{kind});openDialog(`<h2>Secure payroll workflow</h2><p>This is the payroll provider's secure workflow for your connected company. It handles sensitive employee, bank and tax information.</p><p><a href="${esc(response.url)}" target="_blank" rel="noopener noreferrer">Open secure payroll workflow →</a></p><p class="small muted">${esc(response.expires)}</p>`);}
async function providerReviewDialog(id){const result=await api('/api/provider/review',{payrollId:id});const p=result.payroll;openDialog(`<h2>Review payroll · ${esc(p.check_date)}</h2><p>Gross ${currency(Math.round(Number(p.totals?.gross_pay||0)*100))} · Company debit ${currency(Math.round(Number(p.totals?.company_debit||0)*100))}</p><p class="small muted">The owner must approve this exact current calculation. Submission can move real money in production. Employee deposits remain subject to provider processing, funding and settlement.</p><pre>${esc(JSON.stringify(p.totals,null,2))}</pre><form id="provider-submit-form"><input name="payrollId" type="hidden" value="${id}"><input name="fingerprint" type="hidden" value="${esc(result.fingerprint)}"><label>Type RUN PAYROLL ${esc(p.check_date)}<input name="confirmation" autocomplete="off" required></label><label>Owner password<input name="password" type="password" autocomplete="current-password" required></label><button class="primary">Authorize this payroll with provider</button></form>`);}
function employeeDialog(){openDialog(`<h2>Local employee record</h2><p class="small muted">For externally calculated payroll records. Complete tax and bank onboarding in the connected provider, not this local form.</p><form id="employee-form"><label>Name<input name="name" required></label><label>Job title<input name="jobTitle"></label><label>Reference hourly rate ($)<input name="hourlyRate" type="number" min="0" step="0.01" value="0"></label><label>Notes<textarea name="notes"></textarea></label><button class="primary">Save employee</button></form>`);}
function localPayrollDialog(){if(!state.employees.length){employeeDialog();return;}openDialog(`<h2>Record externally calculated payroll</h2><p class="small muted">Enter the provider's actual figures. This form does not calculate withholding, file taxes or transfer funds.</p><form id="local-payroll-form"><div class="form-grid"><label>Employee<select name="employeeId">${state.employees.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></label><label>Pay date<input name="date" type="date" value="${today()}" required></label><label>Period start<input name="periodStart" type="date" required></label><label>Period end<input name="periodEnd" type="date" required></label>${[['gross','Gross wages'],['federal','Federal withheld'],['state','State / local withheld'],['socialSecurity','Employee Social Security'],['medicare','Employee Medicare'],['deductions','Other employee deductions'],['employerSocialSecurity','Employer Social Security'],['employerMedicare','Employer Medicare'],['employerUnemployment','Employer unemployment']].map(([k,label])=>`<label>${label} ($)<input name="${k}" type="number" step="0.01" min="0" value="0" required></label>`).join('')}<label>Reference<input name="reference"></label></div><label><input name="paid" type="checkbox">Net wages were already paid from the bank</label><button class="primary">Post external payroll record</button></form>`);}
function payWagesDialog(id){openDialog(`<h2>Record net-wage payment</h2><p class="small muted">Use only after payment was made outside this app. This records a bank transaction and does not initiate direct deposit.</p><form id="wages-form"><input name="id" type="hidden" value="${esc(id)}"><label>Actual payment date<input name="date" type="date" value="${today()}" required></label><button class="primary">Record payment</button></form>`);}
function taxes(){const liabilities=state.report.trial.filter(a=>a.type==='liability'&&['2100','2151','2152','2153','2154','2155','2156','2160','2250'].includes(a.code));return title('Tax obligations, kept in view.','Monitor official sources for your operating states and track posted payroll and sales-tax liabilities.',`<button data-action="tax-check">Check official sources</button><button class="primary" data-action="tax-payment">Record tax payment</button>`)+`<div class="banner warning"><div><strong>A source change is a review alert, not a tax-rule update.</strong><p>The monitor checks official pages daily while the app is running. It does not guarantee discovery of every state or local law. The connected provider supplies current payroll calculations and filing rules. Unavailable sources are shown as errors.</p></div></div><div class="two-col"><section class="panel"><h2>States of operation</h2><form id="tax-states-form"><div class="state-grid">${Object.entries(state.states).map(([code,name])=>`<label><input type="checkbox" name="state" value="${code}" ${state.operationStates.includes(code)?'checked':''}>${esc(name)}</label>`).join('')}</div><button class="primary">Save operating states</button></form><p class="small muted spaced">Federal sources are included when operating states are selected. Register work locations and state accounts with your payroll provider as well.</p></section><section class="panel"><h2>Liabilities in your company ledger</h2>${table(['Account','Balance'],liabilities.map(a=>`<tr><td>${a.code} · ${esc(a.name)}</td><td class="amount">${currency(-a.balance)}</td></tr>`).join(''))}<p class="small muted">Provider clearing accounts represent accrued payroll, not proof of a filed return or settled payment. Reconcile provider funding and remittances using the actual bank and provider records.</p><h3>Official source status</h3>${state.taxSources.length?state.taxSources.map(s=>`<div class="connection"><strong>${esc(state.states[s.state]||'Federal')}</strong><small>${s.checked_at?esc(s.checked_at.slice(0,19).replace('T',' ')):'Not checked'}</small><p class="small ${s.error?'amount-negative':'muted'}">${esc(s.error||'Source checked; changes go to the review queue.')}</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Official source</a></div>`).join(''):empty('No sources checked yet','Select your states of operation, save, and run a source check.')}</section></div><section class="panel"><h2>Tax-source review queue</h2>${state.taxChanges.length?table(['Detected','State','Status','Effective date',''],state.taxChanges.map(c=>`<tr><td>${esc(c.detected_at.slice(0,10))}</td><td>${esc(state.states[c.state]||'Federal')}</td><td><span class="badge ${c.status==='needs-review'?'warn':''}">${esc(c.status)}</span></td><td>${esc(c.effective_date||'Not determined')}</td><td><button data-action="tax-review" data-id="${c.id}">Review source change</button></td></tr>`).join('')):empty('No source changes queued','A first successful check establishes a baseline. Later differences will be queued for review.')}</section>`;}
function taxReviewDialog(id){const c=state.taxChanges.find(c=>String(c.id)===String(id));openDialog(`<h2>Official source change · ${esc(state.states[c.state]||'Federal')}</h2><p><a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Read the official source</a></p><pre>${esc(c.diff)}</pre><form id="tax-review-form"><input name="id" type="hidden" value="${id}"><label>Review outcome<select name="status"><option value="reviewed">Reviewed / action documented</option><option value="not-applicable">Not applicable to this business</option></select></label><label>Confirmed effective date, if applicable<input name="effectiveDate" type="date" value="${esc(c.effective_date||'')}"></label><label>Review notes / provider action<textarea name="review" required>${esc(c.review||'')}</textarea></label><button class="primary">Save review</button></form>`);}
function taxPaymentDialog(){openDialog(`<h2>Record an actual tax / deduction payment</h2><p class="small muted">This posts a bank payment against the selected liability. It does not submit a tax return or transfer money to a tax agency.</p><form id="tax-payment-form"><label>Liability account<select name="account">${state.accounts.filter(a=>['2100','2151','2152','2153','2154','2155','2156'].includes(a.code)).map(a=>`<option value="${a.code}">${a.code} · ${esc(a.name)}</option>`).join('')}</select></label><label>Date<input name="date" type="date" value="${today()}" required></label><label>Amount ($)<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Confirmation / reference<input name="reference" required></label><label>Memo<input name="memo"></label><button class="primary">Record payment</button></form>`);}
function printing(){return title('The records you need, ready to print.','Clean print layouts with company details, dates, references and totals. Save as PDF through your Windows print dialog.')+`<div class="print-grid">${[['ledger','Company ledger','Posted transactions and their sources.'],['profit-loss','Profit & loss','Company revenue, costs and profit.'],['balance-sheet','Balance sheet','Assets, liabilities and equity.'],['trial-balance','Trial balance','Closing account debit and credit balances.'],['payroll','Payroll register','Payroll recorded directly in this app.'],['assets','Equipment register','Cost, depreciation and book value.'],['tax-liabilities','Tax liability summary','Posted tax and payroll clearing balances.'],['inventory','Inventory planning','Source stock and saved reorder plans.']].map(([type,name,desc])=>`<section class="panel"><h2>${name}</h2><p class="small muted">${desc}</p><a class="print-link" href="/print?type=${type}&${new URLSearchParams({start,end})}" target="_blank" rel="noopener">Open print layout →</a></section>`).join('')}</div><section class="panel"><h2>Individual records & working sheets</h2><p class="muted small">Use View on an invoice, bill, expense or journal to print it. Payroll records include pay-stub links; equipment includes a depreciation schedule.</p>${state.recipes.map(r=>`<p><a href="/print?type=recipe&id=${r.id}" target="_blank" rel="noopener">Production cost sheet · ${esc(r.name)}</a></p>`).join('')}${state.pricing.map(r=>`<p><a href="/print?type=pricing&id=${r.id}" target="_blank" rel="noopener">Retail / wholesale pricing · ${esc(r.name)}</a></p>`).join('')}</section>`;}
document.addEventListener('change',e=>{if(e.target.matches('#asset-form [name=linkedId]'))$('#asset-form [name=linkedSource]').value=e.target.selectedOptions[0]?.dataset.source||'manual';});

function renderNavIcons(){const paths={overview:'M3 11 12 3l9 8M5 10v11h5v-6h4v6h5V10',transactions:'M4 6h16M4 12h16M4 18h16',invoices:'M6 3h9l4 4v14H6z M9 11h7M9 15h5',bills:'M5 3h14v18l-3-2-4 2-4-2-3 2z M8 8h8M8 12h6',inventory:'m3 7 9-4 9 4-9 4z M3 7v10l9 4 9-4V7M12 11v10',pricing:'M3 3h8l10 10-8 8L3 11z M7 7h.01',assets:'M3 16h18M5 16V7h14v9M7 20h10',payroll:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M20 8v6M17 11h6',taxes:'M12 3v18M17 7c0-4-10-4-10 0s10 3 10 7-10 4-10 0',printing:'M6 8V3h12v5M6 17H3V9h18v8h-3M6 14h12v7H6z',costing:'M9 3h6M10 3v7l-6 10h16l-6-10V3M8 15h8',reconcile:'M3 7h16l-4-4M21 17H5l4 4',reports:'M4 21V10h4v11M10 21V3h4v18M16 21V7h4v14',accounts:'M3 4h18v16H3z M3 9h18M9 4v16',imports:'M12 3v12M7 10l5 5 5-5M4 17v4h16v-4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z'};for(const b of document.querySelectorAll('nav [data-view]')){const label=b.querySelector('span')?.textContent||labels[b.dataset.view];b.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[b.dataset.view]||paths.transactions}"/></svg><span>${esc(label)}</span>`;}}

function providerStubsDialog(id){const payroll=state.providerPayrolls.payrolls.find(p=>(p.payroll_uuid||p.uuid)===id);const people=payroll?.employees||[];openDialog(`<h2>Official provider pay stubs</h2><p class="small muted">The provider supplies the employee's official PDF for printing or saving. A pay stub is not proof that a bank deposit settled.</p>${people.length?people.map(e=>`<p><a href="/api/provider/paystub?payrollId=${encodeURIComponent(id)}&employeeId=${encodeURIComponent(e.employee_uuid)}" target="_blank" rel="noopener">${esc([e.first_name,e.last_name].filter(Boolean).join(' ')||e.employee_uuid)} · download official PDF</a></p>`).join(''):'<p>Detailed employee results are not in this cached payroll. Refresh production payroll results or open the provider payroll-history workflow.</p>'}<button data-action="provider-flow" data-kind="history">Open provider payroll history</button>`);}
